func buildMongoWindowFilter(timestampField string, tLo, tHi time.Time, deletedFilter bson.M) bson.M {
	tsCol := strings.TrimSpace(timestampField)
	if tsCol == "" {
		tsCol = "_source_ts"
	}
	loMs := tLo.UnixMilli()
	hiMs := tHi.UnixMilli()
	var filter bson.M
	if tsCol == "_source_ts" {
		filter = bson.M{
			"_source_ts": bson.M{
				"$gte": loMs,
				"$lt":  hiMs,
			},
		}
	} else {
		// [FIX OB-05]: Support both BSON DateTime and int64 epoch-ms representations for domain timestamp fields
		filter = bson.M{
			"$or": bson.A{
				bson.M{
					tsCol: bson.M{
						"$gte": primitive.NewDateTimeFromTime(tLo.UTC()),
						"$lt":  primitive.NewDateTimeFromTime(tHi.UTC()),
					},
				},
				bson.M{
					tsCol: bson.M{
						"$gte": loMs,
						"$lt":  hiMs,
					},
				},
			},
		}
	}
	for k, v := range deletedFilter {
		filter[k] = v
	}
	return filter

